input.command:
cd /Users/kristinarash/Library/Caches/sportsci-batch-123 && for id in Q49 Q50 Q51 Q52 Q53 Q54 Q55 Q56; do node -e '
const fs=require("fs");const id=process.argv[1];const raw=fs.readFileSync("drafts/"+id+".json","utf8");
let d;try{d=JSON.parse(raw)}catch(e){console.log(id,"PARSE ERROR",e.message);process.exit(0)}
const tax=JSON.parse(fs.readFileSync("taxonomy.json","utf8"));
const probs=[];
if(!tax.studyDesigns.includes(d.studyDesign))probs.push("design");
if(!tax.domains.includes(d.primaryDomain))probs.push("primaryDomain");
if(!d.domains.includes(d.primaryDomain))probs.push("primary not in domains");
for(const k of ["domains","audiences","sports","populations"]){for(const v of d[k]){if(!tax[k].includes(v))probs.push(k+":"+v)}}
if(d.decision==="INCLUDE" && d.paper){ if(d.paper.doi!==d.doiFromInputsCheck && false){} }
const emd=(raw.match(/—/g)||[]).length;
console.log(id,d.decision,d.paper&&d.paper.year,d.paper&&d.paper.doi,"emdash="+emd,"problems="+(probs.join("|")||"none"));
' "$id"; done

